import {ROUTES,DEFAULTS,evaluate,rankRoutes,money,dateLabel} from './model.mjs';
import {routeMap} from './route-map.mjs';
export const guideSteps=[
 {title:'Choose a route. See the trade-off.',label:'Choose',copy:'The solid line is the selected corridor. Switching from Cape to Suez costs €1,540 more and arrives nine days earlier.',tip:'Use Routes on the map or select a name in the route options.',cues:['Start with the current Cape plan.','Select Suez Canal in Routes.','Read the updated cost, arrival and planning status.']},
 {title:'Edit a limit. Recheck the options.',label:'Set limits',copy:'Lowering the budget from €22,000 to €19,000 leaves Suez eligible. The Middle Corridor now exceeds the budget.',tip:'Budget, deadline and emissions are editable in the planning-limits bar.',cues:['Budget is €22,000. Two routes meet all three limits.','Open Budget, enter €19,000 and apply it.','One route remains eligible. Rail is €2,860 above the new budget.']},
 {title:'Check two routes. Then compare.',label:'Compare',copy:'Selecting a route changes the map. The check boxes have a different job: they build a two- or three-route comparison.',tip:'Tick the routes you want, then use Compare selected in the action bar.',cues:['Start with the Suez and Middle Corridor options.','Check both boxes, then select Compare selected.','Rail costs €3,440 more and arrives eight days earlier than Suez.']},
 {title:'Add a delay. Read the consequence.',label:'Stress-test',copy:'A seven-day port delay pushes Suez past the deadline. The alternative recommendation changes with the same assumptions.',tip:'Use Port delay in Scenario lab. Reset returns the assumptions to zero.',cues:['At base assumptions, Suez arrives four days before the deadline.','Set Port delay to 7 days. Arrival changes from 10 to 17 Dec.','Suez is three days late. Middle Corridor remains within limits.']},
 {title:'Add a reason. Save the whole plan.',label:'Save',copy:'A saved scenario keeps the route, assumptions and rationale together. It is a planning snapshot, not a booking.',tip:'Open Saved scenarios to revisit a plan or export a backup.',cues:['Select Save scenario for an eligible route.','Give the plan a name and add the reason behind the choice.','The saved snapshot retains its original assumptions.']}
];
const route=(id,settings=DEFAULTS)=>evaluate(ROUTES.find(r=>r.id===id),settings);
const status=(r,icon)=>`<span class="demo-status ${r.feasible?'within':'outside'}">${icon(r.feasible?'check':'alert',14)}${r.feasible?'Within limits':r.failures[0]}</span>`;
const exampleButton=(text,iconName,icon,active=false)=>`<span class="demo-button ${active?'is-target':''}">${icon(iconName,16)}${text}</span>`;
const phaseLabel=['Before','Action','Result'];
function scene(index,phase,icon){
 const suez=route('suez'),rail=route('rail'),cape=route('cape');
 if(index===0){
  const r=phase===0?cape:suez;
  const atlas=routeMap(r,r.id==='cape'?'suez':'cape',{interactive:false}).replace(/height="46"/g,'height="28"').replace(/data-height="46"/g,'data-height="28"').replace(/<text class="location-code"[^>]*>[\s\S]*?<\/text>/g,'');
  return `<div class="demo-route"><div class="tour-atlas case-map">${atlas}<div class="demo-map-picker"><span class="${phase===0?'chosen':''}">Cape</span><span class="${phase>0?'chosen':''} ${phase===1?'is-target':''}">Suez Canal</span></div></div><aside><span class="demo-eyebrow">SELECTED ROUTE</span><h3>${phase===0?'Cape of Good Hope':'Suez Canal'}</h3>${status(r,icon)}<dl><div><dt>Logistics cost</dt><dd>${money(r.cost)}</dd></div><div><dt>Arrival</dt><dd>${dateLabel(r.arrival)}</dd></div></dl><p>${phase===0?'Lowest quote · 5 days late':phase===1?'The line and route details change together.':'+€1,540 · 9 days earlier'}</p></aside></div>`;
 }
 if(index===1){
  const budget=phase===2?19000:22000,settings={...DEFAULTS,budget},rr=route('rail',settings),count=rankRoutes(settings).filter(r=>r.feasible).length;
  return `<div class="demo-limits"><div class="demo-limit-bar"><span class="${phase===1?'is-target':''}">${icon('euro',17)}Budget <b>${money(budget)}</b>${icon('down',13)}</span><span>${icon('calendar',17)}Due <b>14 Dec</b></span><span>${icon('leaf',17)}CO₂e <b>40 t</b></span></div>${phase===1?`<div class="demo-budget-editor"><div><span class="demo-eyebrow">BUDGET LIMIT</span><strong>€19,000</strong></div>${exampleButton('Apply limit','check',icon,true)}</div>`:`<div class="demo-eligibility"><strong>${count}<small> / 6 routes within limits</small></strong><div><span>Suez Canal</span>${status(route('suez',settings),icon)}</div><div><span>Middle Corridor</span>${status(rr,icon)}</div></div>`}<p class="demo-bottom-note">${phase===1?'The deadline and emissions limit stay unchanged.':phase===2?'Rail costs €21,860 — €2,860 above the new budget.':'Eligibility uses all three limits, not price alone.'}</p></div>`;
 }
 if(index===2){
  if(phase===2)return `<div class="demo-matrix"><div class="demo-matrix-row heading"><span>Same shipment</span><strong>Suez Canal</strong><strong>Middle Corridor</strong></div><div class="demo-matrix-row"><span>Logistics cost</span><strong>${money(suez.cost)}</strong><strong>${money(rail.cost)}</strong></div><div class="demo-matrix-row"><span>Arrival</span><strong>${dateLabel(suez.arrival)}</strong><strong>${dateLabel(rail.arrival)}</strong></div><div class="demo-matrix-row"><span>CO₂e</span><strong>${suez.co2} t</strong><strong>${rail.co2} t</strong></div><p class="demo-bottom-note">Middle Corridor: €3,440 more · 8 days earlier · 9.6 t less CO₂e</p></div>`;
  return `<div class="demo-check-table">${[suez,rail].map(r=>`<div class="demo-check-row"><i class="demo-checkbox ${phase===1?'checked':''} ${phase===1?'is-target':''}">${phase===1?icon('check',13):''}</i><span>${r.id==='suez'?'Suez Canal':'Middle Corridor'}<small>${r.service}</small></span><strong>${money(r.cost)}</strong><span>${r.days} days</span></div>`).join('')}<div class="demo-compare-bar"><span>${phase===1?'2 routes selected':'Check boxes add routes to a comparison'}</span>${exampleButton('Compare selected','compare',icon,phase===1)}</div><p class="demo-bottom-note">Check boxes compare. Route names select the map.</p></div>`;
 }
 if(index===3){
  const changed=phase>0,after=route('suez',{...DEFAULTS,delay:changed?7:0}),alternative=route('rail',{...DEFAULTS,delay:7});
  return `<div class="demo-delay"><div class="demo-delay-control"><span>Scenario lab / Port delay</span><strong class="${phase===1?'is-target':''}">${changed?'7':'0'} <small>days</small></strong></div><div class="demo-delay-values"><div><span>Arrival</span><strong>${dateLabel(after.arrival)}</strong><small>${changed?'Was 10 Dec':'At base assumptions'}</small></div><div><span>Deadline buffer</span><strong class="${changed?'caution':'good'}">${changed?'−3':'+4'} <small>days</small></strong><small>Due 14 Dec</small></div></div>${phase===2?`<div class="demo-alternative">${icon('train',21)}<div><span>Eligible alternative</span><strong>Middle Corridor · ${dateLabel(alternative.arrival)}</strong></div>${status(alternative,icon)}</div>`:`<div class="demo-delay-verdict">${status(after,icon)}<span>${changed?'Port delay changes arrival, not the selected baseline.':'Suez currently meets all three limits.'}</span></div>`}</div>`;
 }
 if(phase===2)return `<div class="demo-saved"><div class="demo-saved-heading">${icon('check',22)}<div><span class="demo-eyebrow">SAVED SCENARIO</span><h3>Suez · December delivery</h3></div></div><div class="demo-saved-metrics"><span>€18,420<small>Logistics cost</small></span><span>10 Dec<small>Arrival</small></span><span>Fuel 0% · Delay 0d<small>Saved assumptions</small></span></div><blockquote>Meets the deadline within budget.</blockquote><p class="demo-bottom-note">The snapshot keeps these values when the workspace changes.</p></div>`;
 return `<div class="demo-save-form"><div><span>Scenario name</span><strong>Suez · December delivery</strong></div><div class="${phase===1?'is-target':''}"><span>Why this route? <small>Required</small></span><p class="${phase===0?'placeholder':''}">${phase===0?'Describe the trade-off behind your choice…':'Meets the deadline within budget.'}</p></div><footer><span>${phase===0?'Add a reason to enable saving.':'Route + assumptions + reason are saved together.'}</span><span class="demo-button ${phase===0?'is-disabled':'is-target'}">${icon('bookmark',16)}Save for review</span></footer></div>`;
}
export function guideFrame(index,phase,icon){return `<div class="tour-frame" data-phase="${phase}">${scene(index,phase,icon)}</div>`;}
export function guideView(index,icon,paused=true,phase=0){
 const step=guideSteps[index];
 return `<div class="tour-content"><nav class="tour-chapters" aria-label="Tour chapters">${guideSteps.map((s,i)=>`<button data-action="guide-step" data-value="${i}" aria-current="${i===index?'step':'false'}"><b>${String(i+1).padStart(2,'0')}</b><span>${s.label}</span></button>`).join('')}</nav><div class="tour-preview" data-scene="${index}" data-phase="${phase}" data-paused="${paused}" role="img" aria-label="Example: ${step.title}">${guideFrame(index,phase,icon)}</div><div class="tour-preview-bar"><div class="tour-phases" aria-label="Example frames">${phaseLabel.map((name,i)=>`<button data-action="guide-phase" data-value="${i}" aria-pressed="${i===phase}"><span class="tour-phase-number">${i+1}</span><span class="tour-phase-label">${name}</span></button>`).join('')}</div><div class="tour-player-buttons"><button class="icon-button" data-action="guide-pause" aria-label="${paused?'Play':'Pause'} illustration">${icon(paused?'play':'pause',16)}</button><button class="icon-button" data-action="guide-replay" aria-label="Replay illustration">${icon('reset',16)}</button></div></div><p class="tour-cue" aria-live="polite">${step.cues[phase]}</p><div class="tour-description"><span class="tour-eyebrow">${String(index+1).padStart(2,'0')} / ${String(guideSteps.length).padStart(2,'0')}</span><h3 tabindex="-1">${step.title}</h3><p>${step.copy}</p><div class="tour-tip">${icon('info',16)}<span>${step.tip}</span></div></div><p class="tour-demo-disclaimer">Illustrative example. Your workspace stays unchanged.</p></div><footer class="dialog-footer tour-footer"><button class="text-button" data-action="close">Skip tour</button><div>${index?'<button class="button outline" data-action="guide-back">Back</button>':''}<button class="button primary" data-action="guide-next">${index===guideSteps.length-1?'Start planning':'Next step'} ${icon('arrow',16)}</button></div></footer>`;
}
